contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _minSum, uint _amount, uint _am) public payable {
        require(_amount <= address(this).balance);
        c.SetMinSum(_minSum);
        c.Deposit{value: _amount}();

        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        if (!reverted) {
            assert(balBefore >= _minSum && balBefore >= _am
                && balAfter == balBefore - _am
                && contractBalAfter == contractBalBefore - _am);
        } else {
            assert(balAfter == balBefore && contractBalAfter == contractBalBefore);
        }
    }

    receive() external payable {}
}

